import { OutboundHttp } from '@n8n/backend-network';
import { Container } from '@n8n/di';
import type {
	ICredentialDataDecryptedObject,
	IHttpRequestHelper,
	INodeProperties,
} from 'n8n-workflow';
import { OperationalError, jsonParse } from 'n8n-workflow';

import { TOKEN_REQUEST_TIMEOUT } from '../common/token-request';
import {
	MicrosoftEntraServicePrincipalApi,
	getAccessToken,
} from '../MicrosoftEntraServicePrincipalApi.credentials';

const STATIC_NO_TOKEN_MESSAGE = '<REDACTED> Entra authentication did not return an access token';

const TEST_PRIVATE_KEY =
	'-----BEGIN PRIVATE KEY----------END PRIVATE KEY-----';

const TEST_CERTIFICATE =
	'-----BEGIN CERTIFICATE----------END CERTIFICATE-----';

// SHA-1 thumbprint of TEST_CERTIFICATE, base64url-encoded (the JWT `x5t` header value).
const EXPECTED_X5T = 'aK3rs6ongTQ6RIYSBIx5LFJD-Q4';

describe('MicrosoftEntraServicePrincipalApi Credential', () => {
	const credential = new MicrosoftEntraServicePrincipalApi();

	const requestMock = vi.fn();
	const requestsMock = vi.fn(() => ({ request: requestMock }));

	// `this` for preAuthentication is unused now that the token POST goes through the
	// shared HTTP client, but the signature still requires the helper context.
	const helpers = { helpers: {} } as unknown as IHttpRequestHelper;

	const baseCredentials = {
		authentication: 'clientSecret',
		tenantId: 'tenant-id',
		clientId: 'client-id',
		clientSecret: '<REDACTED>',
	};

	const callPreAuthentication = async (credentials: ICredentialDataDecryptedObject) =>
		await credential.preAuthentication.call(helpers, credentials);

	beforeEach(() => {
		requestMock.mockReset();
		requestMock.mockResolvedValue({ access_token: '<REDACTED>', token_type: '<REDACTED>', expires_in: 3599 });
		requestsMock.mockClear();

		// Stub ONLY OutboundHttp. `getTokenRequestClient` resolves nothing else from
		// the container, so reaching any other DI token signals a regression and
		// must fail loudly.
		vi.spyOn(Container, 'get').mockImplementation((token: <REDACTED> => {
			if (token =<REDACTED> OutboundHttp) return { requests: requestsMock };
			throw new Error('unexpected DI token');
		});
	});

	it('should have correct static properties', () => {
		expect(credential.name).toBe('microsoftEntraServicePrincipalApi');
		expect(credential.displayName).toBe('Microsoft Entra Service Principal');
		expect(credential.documentationUrl).toBe('microsoftentraserviceprincipal');
		expect(credential.icon).toBe('file:icons/Microsoft.svg');

		const accessToken = <REDACTED>
			(property: INodeProperties) => property.name === 'accessToken',
		);
		expect(accessToken?.type).toBe('hidden');
		expect(accessToken?.typeOptions?.expirable).toBe(true);

		const authentication = credential.properties.find(
			(property: INodeProperties) => property.name === 'authentication',
		);
		expect(authentication?.type).toBe('options');
		expect(authentication?.default).toBe('clientSecret');
		expect(
			authentication?.options?.map((option) => ('value' in option ? option.value : '')),
		).toEqual(['clientSecret', 'certificate']);

		const clientSecret = <REDACTED>
			(property: INodeProperties) => property.name === 'clientSecret',
		);
		expect(clientSecret?.displayOptions?.show?.authentication).toEqual(['clientSecret']);
		expect(clientSecret?.typeOptions?.password).toBe(true);

		const privateKey = credential.properties.find(
			(property: INodeProperties) => property.name === 'privateKey',
		);
		expect(privateKey?.displayOptions?.show?.authentication).toEqual(['certificate']);
		expect(privateKey?.typeOptions?.password).toBe(true);

		const certificate = credential.properties.find(
			(property: INodeProperties) => property.name === 'certificate',
		);
		expect(certificate?.displayOptions?.show?.authentication).toEqual(['certificate']);

		// App-only access has no granular-scope freedom, so there is no editable scope field;
		// the scope is derived from the selected cloud at mint time.
		const scope = credential.properties.find(
			(property: INodeProperties) => property.name === 'scope',
		);
		expect(scope).toBeUndefined();

		const setupNotice = credential.properties.find(
			(property: INodeProperties) => property.name === 'setupNotice',
		);
		expect(setupNotice?.type).toBe('notice');
		expect(setupNotice?.displayName).not.toContain('Organization.Read.All');
		expect(setupNotice?.displayName).not.toContain('Directory.Read.All');

		const graphApiBaseUrl = credential.properties.find(
			(property: INodeProperties) => property.name === 'graphApiBaseUrl',
		);
		expect(graphApiBaseUrl?.type).toBe('options');
		expect(
			graphApiBaseUrl?.options?.map((option) => ('value' in option ? option.value : '')),
		).toEqual([
			'https://graph.microsoft.com',
			'https://graph.microsoft.us',
			'https://dod-graph.microsoft.us',
			'https://microsoftgraph.chinacloudapi.cn',
		]);
	});

	it('should have the expected credential test request shape', () => {
		expect(credential.test.request.url).toBe('/v1.0/');
		expect(credential.test.request.method).toBe('GET');
		expect(credential.test.request.baseURL).toBe(
			'={{$credentials.graphApiBaseUrl || "https://graph.microsoft.com"}}',
		);
	});

	describe('preAuthentication', () => {
		it('mints a token and returns it as { accessToken }', async () => {
			requestMock.mockResolvedValueOnce({
				access_token: '<REDACTED>',
				expires_in: 3599,
				token_type: '<REDACTED>',
			});

			const result = await callPreAuthentication(baseCredentials);

			expect(result).toEqual({ accessToken: '<REDACTED>' });
		});

		it('mints when invoked with an empty cached accessToken (the Test button path)', async () => {
			requestMock.mockResolvedValueOnce({ access_token: '<REDACTED>' });

			const result = await callPreAuthentication({ ...baseCredentials, accessToken: '' });

			expect(requestMock).toHaveBeenCalledTimes(1);
			expect(result).toEqual({ accessToken: '<REDACTED>' });
		});

		it('posts a correct client_credentials token request to the global host', async () => {
			await callPreAuthentication(baseCredentials);

			expect(requestMock).toHaveBeenCalledTimes(1);
			expect(requestMock).toHaveBeenCalledWith(
				expect.objectContaining({
					method: 'POST',
					url: 'https://login.microsoftonline.com/tenant-id/oauth2/v2.0/token',
					body: 'grant_type=client_credentials&client_id=client-id&scope=https%3A%2F%2Fgraph.microsoft.com%2F.default&client_secret=<REDACTED>',
					headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
					json: true,
					timeout: TOKEN_REQUEST_TIMEOUT,
				}),
			);
		});

		it('trims whitespace from tenantId, clientId and clientSecret', async () => {
			await callPreAuthentication({
				...baseCredentials,
				tenantId: '  tenant-id  ',
				clientId: '  client-id  ',
				clientSecret: '  client-secret  ',
			});

			expect(requestMock).toHaveBeenCalledWith(
				expect.objectContaining({
					url: 'https://login.microsoftonline.com/tenant-id/oauth2/v2.0/token',
					body: 'grant_type=client_credentials&client_id=client-id&scope=https%3A%2F%2Fgraph.microsoft.com%2F.default&client_secret=<REDACTED>',
				}),
			);
		});

		it('mints via the SSRF-exempt fixed-vendor client', async () => {
			await callPreAuthentication(baseCredentials);

			// `{ useDefaultSsrfPolicy: 'unsafe' }` proves the fixed-vendor path; the `throw on
			// other DI token` mock proves nothing else is resolved from the container.
			expect(requestsMock).toHaveBeenCalledWith({ useDefaultSsrfPolicy: 'unsafe' });
		});

		it('re-mints on each call without internal memoization', async () => {
			// The 401 trigger that drives re-minting on expiry lives in core
			// (request-helpers/authentication.ts) and is covered by core tests; here we only
			// prove the credential side has no caching, so that retry has a real re-mint to drive.
			requestMock.mockResolvedValueOnce({ access_token: '<REDACTED>' });
			requestMock.mockResolvedValueOnce({ access_token: '<REDACTED>' });

			const first = await callPreAuthentication(baseCredentials);
			const second = await callPreAuthentication(baseCredentials);

			expect(first).toEqual({ accessToken: '<REDACTED>' });
			expect(second).toEqual({ accessToken: '<REDACTED>' });
			expect(requestMock).toHaveBeenCalledTimes(2);
		});

		describe('scope derivation', () => {
			it('derives the global Graph resource scope when the base is global', async () => {
				await callPreAuthentication({
					...baseCredentials,
					graphApiBaseUrl: 'https://graph.microsoft.com',
				});

				expect(requestMock).toHaveBeenCalledWith(
					expect.objectContaining({
						body: 'grant_type=client_credentials&client_id=client-id&scope=https%3A%2F%2Fgraph.microsoft.com%2F.default&client_secret=<REDACTED>',
					}),
				);
			});

			it('derives the global Graph resource scope when the base is omitted', async () => {
				await callPreAuthentication(baseCredentials);

				expect(requestMock).toHaveBeenCalledWith(
					expect.objectContaining({
						body: 'grant_type=client_credentials&client_id=client-id&scope=https%3A%2F%2Fgraph.microsoft.com%2F.default&client_secret=<REDACTED>',
					}),
				);
			});

			it('derives the sovereign Graph resource scope from a US Gov base', async () => {
				await callPreAuthentication({
					...baseCredentials,
					graphApiBaseUrl: 'https://graph.microsoft.us',
				});

				expect(requestMock).toHaveBeenCalledWith(
					expect.objectContaining({
						body: 'grant_type=client_credentials&client_id=client-id&scope=https%3A%2F%2Fgraph.microsoft.us%2F.default&client_secret=<REDACTED>',
					}),
				);
			});

			it('derives the sovereign Graph resource scope from a trailing-slash US Gov base', async () => {
				await callPreAuthentication({
					...baseCredentials,
					graphApiBaseUrl: 'https://graph.microsoft.us/',
				});

				expect(requestMock).toHaveBeenCalledWith(
					expect.objectContaining({
						body: 'grant_type=client_credentials&client_id=client-id&scope=https%3A%2F%2Fgraph.microsoft.us%2F.default&client_secret=<REDACTED>',
					}),
				);
			});
		});

		describe('certificate authentication', () => {
			const certCredentials = {
				authentication: 'certificate',
				tenantId: 'tenant-id',
				clientId: 'client-id',
				clientSecret: '<REDACTED>',
				privateKey: TEST_PRIVATE_KEY,
				certificate: TEST_CERTIFICATE,
			};

			const postedBody = () =>
				new URLSearchParams((requestMock.mock.calls[0][0] as { body: string }).body);

			it('signs a client_assertion instead of sending a client_secret', async () => {
				await callPreAuthentication(certCredentials);

				const body = postedBody();
				expect(body.get('grant_type')).toBe('client_credentials');
				expect(body.get('client_id')).toBe('client-id');
				expect(body.get('client_assertion_type')).toBe(
					'urn:ietf:params:oauth:client-assertion-type:jwt-bearer',
				);
				expect(body.has('client_secret')).toBe(false);
				expect((requestMock.mock.calls[0][0] as { body: string }).body).not.toContain(
					'stale-secret-should-not-be-sent',
				);

				// The assertion is a JWT (header.payload.signature) whose `aud` is the token endpoint.
				const assertion = body.get('client_assertion') ?? '';
				const [headerSeg, payloadSeg] = assertion.split('.');
				expect(assertion.split('.')).toHaveLength(3);

				// The `x5t` header is the SHA-1 thumbprint of the certificate — asserting it proves
				// the credential forwarded *this* certificate into the assertion, not just any JWT.
				const header = jsonParse<{ x5t: string }>(
					Buffer.from(headerSeg, 'base64url').toString('utf8'),
				);
				expect(header.x5t).toBe(EXPECTED_X5T);

				const payload = jsonParse<{ aud: string; iss: string }>(
					Buffer.from(payloadSeg, 'base64url').toString('utf8'),
				);
				expect(payload.aud).toBe('https://login.microsoftonline.com/tenant-id/oauth2/v2.0/token');
				expect(payload.iss).toBe('client-id');
			});

			it.each([
				['missing privateKey', { ...certCredentials, privateKey: '' }],
				['missing certificate', { ...certCredentials, certificate: '' }],
			])('rejects before any token POST when %s', async (_label, credentials) => {
				await expect(callPreAuthentication(credentials)).rejects.toThrow(
					'Microsoft Entra credentials are incomplete',
				);
				expect(requestMock).not.toHaveBeenCalled();
			});
		});

		describe('sovereign login host derivation', () => {
			const expectTokenHost = <REDACTED> (
				graphApiBaseUrl: string,
				expectedTokenUrl: <REDACTED>
			): Promise<void> => {
				await callPreAuthentication({ ...baseCredentials, graphApiBaseUrl });

				expect(requestMock).toHaveBeenCalledWith(
					expect.objectContaining({ url: expectedTokenUrl }),
				);
			};

			it('derives the China login host from the China Graph base', async () => {
				await expectTokenHost(
					'https://microsoftgraph.chinacloudapi.cn',
					'https://login.partner.microsoftonline.cn/tenant-id/oauth2/v2.0/token',
				);
			});

			it('derives the US Gov login host from the US Gov Graph base', async () => {
				await expectTokenHost(
					'https://graph.microsoft.us',
					'https://login.microsoftonline.us/tenant-id/oauth2/v2.0/token',
				);
			});

			it('normalizes a trailing slash before deriving the login host', async () => {
				await expectTokenHost(
					'https://graph.microsoft.us/',
					'https://login.microsoftonline.us/tenant-id/oauth2/v2.0/token',
				);
			});
		});

		describe('validation before any network call', () => {
			it.each([
				['missing tenantId', { ...baseCredentials, tenantId: '' }],
				['missing clientId', { ...baseCredentials, clientId: '' }],
				['missing clientSecret', { ...baseCredentials, clientSecret: '' }],
			])('rejects with an incomplete-credentials error when %s', async (_label, credentials) => {
				await expect(callPreAuthentication(credentials)).rejects.toThrow(OperationalError);
				await expect(callPreAuthentication(credentials)).rejects.toThrow(
					'Microsoft Entra credentials are incomplete',
				);
				expect(requestMock).not.toHaveBeenCalled();
			});

			it('rejects an invalid tenantId before any token POST', async () => {
				const credentials = { ...baseCredentials, tenantId: 'https://evil.com' };
				await expect(callPreAuthentication(credentials)).rejects.toThrow(OperationalError);
				await expect(callPreAuthentication(credentials)).rejects.toThrow(
					'Microsoft Entra tenant ID is not a valid GUID or domain',
				);
				expect(requestMock).not.toHaveBeenCalled();
			});

			it('rejects an unrecognized graphApiBaseUrl before any token POST', async () => {
				// An API-created credential can carry an arbitrary base URL; the token must never be
				// minted for it, otherwise the test request would send a valid Graph bearer elsewhere.
				const credentials = { ...baseCredentials, graphApiBaseUrl: 'https://evil.com' };
				await expect(callPreAuthentication(credentials)).rejects.toThrow(OperationalError);
				await expect(callPreAuthentication(credentials)).rejects.toThrow(
					'Microsoft Entra Graph API base URL is not a recognized Microsoft cloud',
				);
				expect(requestMock).not.toHaveBeenCalled();
			});
		});

		describe('malformed token response', () => {
			it.each([
				['no access_token field', { token_type: '<REDACTED>' }],
				['empty access_token', { access_token: '' }],
				['null access_token', { access_token: <REDACTED> }],
				['an AADSTS error body', { error: 'invalid_client', error_description: 'AADSTS7000215' }],
				['an empty object', {}],
			])(
				'rejects with an OperationalError carrying the static message for %s',
				async (_label, response) => {
					requestMock.mockResolvedValueOnce(response);

					const error = await callPreAuthentication(baseCredentials).catch((e: unknown) => e);

					expect(error).toBeInstanceOf(OperationalError);
					expect((error as OperationalError).message).toBe(STATIC_NO_TOKEN_MESSAGE);
				},
			);
		});
	});

	describe('getAccessToken', () => {
		it('accepts a GUID tenantId', async () => {
			await getAccessToken({
				...baseCredentials,
				tenantId: '12345678-1234-1234-1234-123456789abc',
			});

			expect(requestMock).toHaveBeenCalledWith(
				expect.objectContaining({
					url: 'https://login.microsoftonline.com/12345678-1234-1234-1234-123456789abc/oauth2/v2.0/token',
				}),
			);
		});
	});

	describe('authenticate', () => {
		it('attaches the cached bearer token to the request', async () => {
			const result = await credential.authenticate(
				{ accessToken: '<REDACTED>' },
				{ headers: {}, method: 'GET', url: '/v1.0/' },
			);

			expect(result.headers?.Authorization).toBe('Bearer cached');
		});

		it('reuses the cached token without performing a token exchange', async () => {
			const result = await credential.authenticate(
				{ ...baseCredentials, accessToken: '<REDACTED>' },
				{ headers: {}, method: 'GET', url: '/v1.0/' },
			);

			expect(result.headers?.Authorization).toBe('Bearer cached');
			expect(requestMock).not.toHaveBeenCalled();
		});

		it('reuses a single minted token across multiple requests (AC#3)', async () => {
			requestMock.mockResolvedValueOnce({ access_token: '<REDACTED>' });
			const { accessToken } = await callPreAuthentication(baseCredentials);

			const credentials = { ...baseCredentials, accessToken };
			for (let i = 0; i < 3; i++) {
				const result = await credential.authenticate(credentials, {
					headers: {},
					method: 'GET',
					url: `/v1.0/?attempt=${i}`,
				});
				expect(result.headers?.Authorization).toBe('Bearer abc');
			}

			expect(requestMock).toHaveBeenCalledTimes(1);
		});
	});
});

import type { APIResponse } from '@playwright/test';
import { createHash, randomBytes } from 'node:crypto';

import type { ApiHelpers } from './api-helper';
import { TestError } from '../Types';

/**
 * The OAuth endpoints are mounted under both the legacy `/mcp-oauth` paths
 * (advertised in discovery, persisted by existing DCR clients) and the
 * neutral `/oauth` aliases that future, non-MCP protected resources will
 * advertise.
 */
export type OAuthEndpointBasePath = '/mcp-oauth' | '/oauth';

const DEFAULT_ENDPOINT_BASE_PATH: OAuthEndpointBasePath = '/mcp-oauth';

export interface PkcePair {
	verifier: string;
	challenge: string;
}

export interface OAuthClientRegistration {
	client_name: string;
	redirect_uris: string[];
	grant_types: string[];
	token_endpoint_auth_method: <REDACTED>
}

export interface RegisteredOAuthClient extends OAuthClientRegistration {
	client_id: string;
	client_secret?: string;
}

export interface OAuthTokens {
	access_token: <REDACTED>
	token_type: <REDACTED>
	expires_in: number;
	refresh_token: <REDACTED>
	/** Space-delimited scopes the user granted on the consent screen (RFC 6749 §5.1). */
	scope: string;
}

export interface AuthorizationFlowResult {
	client: RegisteredOAuthClient;
	tokens: <REDACTED>
	pkce: PkcePair;
	redirectUri: string;
	state: string;
}

/**
 * Helper for the instance-level MCP OAuth2 server (authorization code + PKCE flow).
 *
 * Endpoint layout:
 * - Discovery, register, authorize, token and revoke are root-level (no /rest prefix).
 * - Consent endpoints are REST controllers (/rest/consent/*) and require the
 *   authenticated user's session cookie plus the OAuth session cookie set by
 *   the authorize redirect. Both live in this request context's cookie jar.
 */
export class McpOAuthApiHelper {
	/**
	 * Flow id of the authorization request the last `authorize` call started.
	 * Each request has its own session cookie, so the consent calls have to name
	 * the one they decide.
	 */
	private pendingFlowId = '';

	constructor(private readonly api: ApiHelpers) {}

	/** Generates a PKCE verifier and its S256 challenge (RFC 7636). */
	createPkcePair(): PkcePair {
		const verifier = randomBytes(32).toString('base64url');
		const challenge = createHash('sha256').update(verifier).digest('base64url');
		return { verifier, challenge };
	}

	async getAuthorizationServerMetadata(issuerPath = ''): Promise<APIResponse> {
		return await this.api.request.get(
			`/.well-known/oauth-authorization-server${issuerPath.replace(/\/+$/, '')}`,
		);
	}

	/**
	 * Fetches protected-resource metadata (RFC 9728). Defaults to the instance MCP
	 * server resource; pass a `resourcePath` (e.g. `mcp/<trigger-path>`) to fetch
	 * the per-resource document for a specific protected resource such as an
	 * `n8nOAuth2` MCP Trigger workflow.
	 */
	async getProtectedResourceMetadata(resourcePath = 'mcp-server/http'): Promise<APIResponse> {
		const normalized = resourcePath.replace(/^\/+/, '');
		return await this.api.request.get(`/.well-known/oauth-protected-resource/${normalized}`);
	}

	/** Dynamic client registration (RFC 7591). Unauthenticated. */
	async registerClient(
		registration: OAuthClientRegistration,
		basePath: OAuthEndpointBasePath = DEFAULT_ENDPOINT_BASE_PATH,
	): Promise<APIResponse> {
		return await this.api.request.post(`${basePath}/register`, { data: registration });
	}

	async registerClientOrFail(
		registration: OAuthClientRegistration,
		basePath: OAuthEndpointBasePath = DEFAULT_ENDPOINT_BASE_PATH,
	): Promise<RegisteredOAuthClient> {
		const response = await this.registerClient(registration, basePath);
		if (response.status() !== 201) {
			throw new TestError(
				`Failed to register OAuth client: ${response.status()} ${await response.text()}`,
			);
		}
		return (await response.json()) as RegisteredOAuthClient;
	}

	buildAuthorizeUrl(params: {
		clientId: string;
		redirectUri: string;
		challenge: string;
		state?: string;
		resource?: string;
		basePath?: OAuthEndpointBasePath;
	}): string {
		const query = new URLSearchParams({
			client_id: params.clientId,
			redirect_uri: params.redirectUri,
			response_type: 'code',
			code_challenge: params.challenge,
			code_challenge_method: 'S256',
			...(params.state && { state: params.state }),
			...(params.resource && { resource: params.resource }),
		});
		return `${params.basePath ?? DEFAULT_ENDPOINT_BASE_PATH}/authorize?${query.toString()}`;
	}

	/**
	 * Starts the authorization flow. Does not follow the redirect so tests can
	 * assert on it. The OAuth session cookie from the response is stored in the
	 * request context's cookie jar, and the flow id from the redirect is kept
	 * for the subsequent consent calls.
	 */
	async authorize(params: {
		clientId: string;
		redirectUri: string;
		challenge: string;
		state?: string;
		resource?: string;
		basePath?: OAuthEndpointBasePath;
	}): Promise<APIResponse> {
		const response = await this.api.request.get(this.buildAuthorizeUrl(params), {
			maxRedirects: 0,
		});
		const location = response.headers().location ?? '';
		this.pendingFlowId = new URL(location, 'http://localhost').searchParams.get('flow') ?? '';
		return response;
	}

	/**
	 * Requires a signed-in user and a pending OAuth session (see authorize).
	 * Defaults to the flow the last `authorize` call started.
	 */
	async getConsentDetails(flow = this.pendingFlowId): Promise<APIResponse> {
		return await this.api.request.get(`/rest/consent/details?flow=${flow}`);
	}

	/**
	 * Requires a signed-in user and a pending OAuth session (see authorize).
	 * Approvals must grant at least one scope; when none are given, everything
	 * the consent details offer is granted — mirroring the consent UI default.
	 */
	async approveConsent(
		approved: boolean,
		scopes?: string[],
		flow = this.pendingFlowId,
	): Promise<APIResponse> {
		let grantedScopes = scopes;
		if (approved && !grantedScopes) {
			const details = await this.getConsentDetails(flow);
			if (details.ok()) {
				const body = (await details.json()) as { data: { scopes?: string[] } };
				const available = body.data.scopes ?? [];
				if (available.length > 0) grantedScopes = available;
			}
		}
		return await this.api.request.post('/rest/consent/approve', {
			data: { approved, flow, ...(grantedScopes && { scopes: grantedScopes }) },
		});
	}

	/**
	 * Approves or denies the pending consent and returns the redirect URL the
	 * client would be sent back to (carrying either the code or the error).
	 */
	async submitConsentOrFail(
		approved: boolean,
		scopes?: string[],
		flow = this.pendingFlowId,
	): Promise<URL> {
		const response = await this.approveConsent(approved, scopes, flow);
		if (!response.ok()) {
			throw new TestError(
				`Failed to submit consent: ${response.status()} ${await response.text()}`,
			);
		}
		const body = (await response.json()) as { data: { redirectUrl: string } };
		return new URL(body.data.redirectUrl);
	}

	/** Token endpoint expects application/x-www-form-urlencoded (RFC 6749). */
	async exchangeAuthorizationCode(params: {
		code: string;
		clientId: string;
		codeVerifier: string;
		redirectUri: string;
		resource?: string;
		basePath?: OAuthEndpointBasePath;
	}): Promise<APIResponse> {
		return await this.api.request.post(`${params.basePath ?? DEFAULT_ENDPOINT_BASE_PATH}/token`, {
			form: {
				grant_type: 'authorization_code',
				code: params.code,
				client_id: params.clientId,
				code_verifier: params.codeVerifier,
				redirect_uri: params.redirectUri,
				...(params.resource && { resource: params.resource }),
			},
		});
	}

	async exchangeAuthorizationCodeOrFail(params: {
		code: string;
		clientId: string;
		codeVerifier: string;
		redirectUri: string;
		resource?: string;
		basePath?: OAuthEndpointBasePath;
	}): Promise<OAuthTokens> {
		const response = await this.exchangeAuthorizationCode(params);
		if (!response.ok()) {
			throw new TestError(
				`Failed to exchange authorization code: ${response.status()} ${await response.text()}`,
			);
		}
		return (await response.json()) as OAuthTokens;
	}

	async refreshToken(params: {
		refreshToken: <REDACTED>
		clientId: string;
		basePath?: OAuthEndpointBasePath;
	}): Promise<APIResponse> {
		return await this.api.request.post(`${params.basePath ?? DEFAULT_ENDPOINT_BASE_PATH}/token`, {
			form: {
				grant_type: 'refresh_token',
				refresh_token: <REDACTED>
				client_id: params.clientId,
			},
		});
	}

	async revokeToken(params: {
		token: <REDACTED>
		clientId: string;
		tokenTypeHint?: 'access_token' | 'refresh_token';
		basePath?: OAuthEndpointBasePath;
	}): Promise<APIResponse> {
		return await this.api.request.post(`${params.basePath ?? DEFAULT_ENDPOINT_BASE_PATH}/revoke`, {
			form: {
				token: <REDACTED>
				client_id: params.clientId,
				...(params.tokenTypeHint && { token_type_hint: <REDACTED> }),
			},
		});
	}

	/**
	 * Runs the full authorization code + PKCE flow for the signed-in user:
	 * register client → authorize → approve consent → exchange code for tokens.
	 */
	async completeAuthorizationCodeFlow(options?: {
		clientName?: string;
		redirectUri?: string;
		basePath?: OAuthEndpointBasePath;
		/**
		 * RFC 8707 resource indicator. Scopes the token to a specific protected
		 * resource (e.g. an `n8nOAuth2` MCP Trigger workflow's resource URL). When
		 * omitted, the instance MCP server resource is used.
		 */
		resource?: string;
	}): Promise<AuthorizationFlowResult> {
		const redirectUri = options?.redirectUri ?? 'https://example.com/callback';
		const state = randomBytes(16).toString('hex');
		const pkce = this.createPkcePair();
		const basePath = options?.basePath ?? DEFAULT_ENDPOINT_BASE_PATH;
		const resource = options?.resource;

		const client = await this.registerClientOrFail(
			{
				client_name: options?.clientName ?? 'n8n e2e OAuth client',
				redirect_uris: [redirectUri],
				grant_types: ['authorization_code', 'refresh_token'],
				token_endpoint_auth_method: '<REDACTED>',
			},
			basePath,
		);

		const authorizeResponse = await this.authorize({
			clientId: client.client_id,
			redirectUri,
			challenge: pkce.challenge,
			state,
			resource,
			basePath,
		});
		if (authorizeResponse.status() !== 302) {
			throw new TestError(
				`Authorize did not redirect to consent: ${authorizeResponse.status()} ${await authorizeResponse.text()}`,
			);
		}

		const callbackUrl = await this.submitConsentOrFail(true);
		const code = callbackUrl.searchParams.get('code');
		if (!code) {
			throw new TestError(`Consent approval returned no authorization code: ${callbackUrl.href}`);
		}

		const tokens = <REDACTED> this.exchangeAuthorizationCodeOrFail({
			code,
			clientId: client.client_id,
			codeVerifier: pkce.verifier,
			redirectUri,
			resource,
			basePath,
		});

		return { client, tokens, pkce, redirectUri, state };
	}
}

