import { createWorkflowWithHistory, setActiveVersion, testDb } from '@n8n/backend-test-utils';
import { GlobalConfig } from '@n8n/config';
import type { User } from '@n8n/db';
import { WebhookRepository } from '@n8n/db';
import { Container } from '@n8n/di';
import type { INode, IWebhookData, IWorkflowBase } from 'n8n-workflow';
import { randomUUID } from 'node:crypto';

import { createOwner } from '@test-integration/db/users';
import { setupTestServer } from '@test-integration/utils';

import { MCP_TRIGGER_NODE_TYPE } from '@/constants';
import { OAuthTokenService } from '@/modules/oauth-server/oauth-token.service';
import { CacheService } from '@n8n/backend-services';
import { UrlService } from '@n8n/backend-services';
import { TestWebhookRegistrationsService } from '@/webhooks/test-webhook-registrations.service';

const testServer = setupTestServer({ modules: ['oauth-server', 'mcp'], endpointGroups: ['mcp'] });

let owner: User;
let mcpEndpoint: string;
let mcpTestEndpoint: string;
let registrations: TestWebhookRegistrationsService;

const webhookBaseUrl = () => Container.get(UrlService).getWebhookBaseUrl().replace(/\/$/, '');
const testWebhookBaseUrl = () =>
	Container.get(UrlService).getTestWebhookBaseUrl().replace(/\/$/, '');

const testResourceUrlFor = (webhookPath: string) =>
	`${testWebhookBaseUrl()}/${mcpTestEndpoint}/${webhookPath}`;

const prmPathFor = (webhookPath: string) =>
	`/.well-known/oauth-protected-resource/${mcpTestEndpoint}/${webhookPath}`;

const mcpTriggerNode = ({
	name = 'MCP Server Trigger',
	authentication = 'n8nOAuth2',
	disabled = false,
}: {
	name?: string;
	authentication?: string;
	disabled?: boolean;
} = {}): INode => ({
	id: randomUUID(),
	name,
	type: MCP_TRIGGER_NODE_TYPE,
	typeVersion: 2,
	position: [0, 0],
	disabled,
	parameters: { path: 'unused', authentication },
});

/**
 * Mirrors what `TestWebhooks.needsWebhook` registers when the user tests an
 * MCP trigger in the editor. The workflow does not need to exist in the DB:
 * the registration is self-contained.
 */
const registerTestWebhook = async (
	webhookPath: string,
	node: INode,
	{
		workflowId = randomUUID(),
		workflowName = 'My test workflow',
	}: { workflowId?: string; workflowName?: string } = {},
) => {
	await registrations.register({
		version: 1,
		workflowEntity: {
			id: workflowId,
			name: workflowName,
			active: false,
			nodes: [node],
			connections: {},
		} as IWorkflowBase,
		webhook: {
			httpMethod: 'POST',
			path: webhookPath,
			node: node.name,
			workflowId,
		} as IWebhookData,
	});
	return { workflowId, workflowName };
};

beforeAll(async () => {
	owner = await createOwner();
	const { endpoints } = Container.get(GlobalConfig);
	mcpEndpoint = endpoints.mcp;
	mcpTestEndpoint = endpoints.mcpTest;
	registrations = Container.get(TestWebhookRegistrationsService);
});

afterEach(async () => {
	await Container.get(CacheService).reset(); // test webhook registrations live in the cache
	await testDb.truncate([
		'AccessToken',
		'RefreshToken',
		'AuthorizationCode',
		'OAuthClient',
		'WebhookEntity',
		'SharedWorkflow',
		'WorkflowEntity',
		'WorkflowHistory',
	]);
});

describe('protected resource metadata for test MCP triggers', () => {
	test('should serve the metadata document while a test registration exists', async () => {
		const webhookPath = randomUUID();
		await registerTestWebhook(webhookPath, mcpTriggerNode());

		const response = await testServer.restlessAgent.get(prmPathFor(webhookPath));

		expect(response.statusCode).toBe(200);
		// exact match: `scopes_supported` must be absent (the resource advertises no scopes)
		expect(response.body).toEqual({
			resource: testResourceUrlFor(webhookPath),
			bearer_methods_supported: ['header'],
			authorization_servers: [expect.any(String)],
		});
	});

	test('should resolve from the registration alone, without the workflow in the DB', async () => {
		const webhookPath = randomUUID();
		const { workflowName } = await registerTestWebhook(webhookPath, mcpTriggerNode(), {
			workflowName: 'Unsaved workflow',
		});

		const response = await testServer.restlessAgent.get(prmPathFor(webhookPath));

		expect(response.statusCode).toBe(200);
		expect(workflowName).toBe('Unsaved workflow');
	});

	test('should not resolve an unknown test path', async () => {
		const response = await testServer.restlessAgent.get(prmPathFor(randomUUID()));

		expect(response.statusCode).toBe(404);
	});

	test('should not resolve when the registration node name does not match', async () => {
		const webhookPath = randomUUID();
		// the webhook points at a node name absent from the registered workflow
		await registrations.register({
			version: 1,
			workflowEntity: {
				id: randomUUID(),
				name: 'My test workflow',
				active: false,
				nodes: [mcpTriggerNode()],
				connections: {},
			} as IWorkflowBase,
			webhook: {
				httpMethod: 'POST',
				path: webhookPath,
				node: 'Ghost node',
				workflowId: randomUUID(),
			} as IWebhookData,
		});

		const response = await testServer.restlessAgent.get(prmPathFor(webhookPath));

		expect(response.statusCode).toBe(404);
	});

	test.each([
		['authentication is none', mcpTriggerNode({ authentication: 'none' })],
		['authentication is bearerAuth', mcpTriggerNode({ authentication: 'bearerAuth' })],
		['the node is disabled', mcpTriggerNode({ disabled: true })],
	])('should not resolve when %s', async (_, node) => {
		const webhookPath = randomUUID();
		await registerTestWebhook(webhookPath, node);

		const response = await testServer.restlessAgent.get(prmPathFor(webhookPath));

		expect(response.statusCode).toBe(404);
	});

	test('should stop resolving as soon as the registration is removed', async () => {
		const webhookPath = randomUUID();
		await registerTestWebhook(webhookPath, mcpTriggerNode());

		expect((await testServer.restlessAgent.get(prmPathFor(webhookPath))).statusCode).toBe(200);

		await registrations.deregister(registrations.toKey({ httpMethod: 'POST', path: webhookPath }));

		expect((await testServer.restlessAgent.get(prmPathFor(webhookPath))).statusCode).toBe(404);
	});
});

describe('test vs production resources', () => {
	const registerOAuthClient = async () => {
		const response = await testServer.restlessAgent.post('/mcp-oauth/register').send({
			client_name: 'test-resolver-tests',
			redirect_uris: ['https://example.com/callback'],
			grant_types: ['authorization_code'],
			token_endpoint_auth_method: '<REDACTED>',
		});
		expect(response.statusCode).toBe(201);
		return response.body.client_id as string;
	};

	test('should serve the same trigger path as two distinct resources', async () => {
		const webhookPath = randomUUID();
		const node = mcpTriggerNode();

		// production: active workflow with published version + webhook row
		const workflow = await createWorkflowWithHistory({ active: true, nodes: [node] }, owner);
		await setActiveVersion(workflow.id, workflow.versionId);
		await Container.get(WebhookRepository).insert({
			workflowId: workflow.id,
			webhookPath,
			method: 'POST',
			node: node.name,
		});

		// test: editor registration for the same path
		await registerTestWebhook(webhookPath, node, { workflowId: workflow.id });

		const production = await testServer.restlessAgent.get(
			`/.well-known/oauth-protected-resource/${mcpEndpoint}/${webhookPath}`,
		);
		const test = await testServer.restlessAgent.get(prmPathFor(webhookPath));

		expect(production.statusCode).toBe(200);
		expect(test.statusCode).toBe(200);
		expect(production.body.resource).not.toBe(test.body.resource);
	});

	test('should reject a test-resource token at the production resource and vice versa', async () => {
		const webhookPath = randomUUID();
		const node = mcpTriggerNode();

		const workflow = await createWorkflowWithHistory({ active: true, nodes: [node] }, owner);
		await setActiveVersion(workflow.id, workflow.versionId);
		await Container.get(WebhookRepository).insert({
			workflowId: workflow.id,
			webhookPath,
			method: 'POST',
			node: node.name,
		});
		await registerTestWebhook(webhookPath, node, { workflowId: workflow.id });

		const clientId = await registerOAuthClient();
		const tokenService = <REDACTED>
		const productionResourceUrl = `${webhookBaseUrl()}/${mcpEndpoint}/${webhookPath}`;
		const testResourceUrl = testResourceUrlFor(webhookPath);

		const testToken = <REDACTED> clientId, testResourceUrl, []);
		await tokenService.saveTokenPair(
			testToken.accessToken,
			testToken.refreshToken,
			clientId,
			owner.id,
			[],
			testToken.audience,
		);
		const productionToken = <REDACTED>
			owner.id,
			clientId,
			productionResourceUrl,
			[],
		);
		await tokenService.saveTokenPair(
			productionToken.accessToken,
			productionToken.refreshToken,
			clientId,
			owner.id,
			[],
			productionToken.audience,
		);

		await expect(
			tokenService.verifyAccessToken(testToken.accessToken, testResourceUrl),
		).resolves.toMatchObject({ clientId });
		await expect(
			tokenService.verifyAccessToken(productionToken.accessToken, productionResourceUrl),
		).resolves.toMatchObject({ clientId });

		await expect(
			tokenService.verifyAccessToken(testToken.accessToken, productionResourceUrl),
		).rejects.toThrow();
		await expect(
			tokenService.verifyAccessToken(productionToken.accessToken, testResourceUrl),
		).rejects.toThrow();
	});
});

import {
	createWorkflowWithHistory,
	setActiveVersion,
	shareWorkflowWithUsers,
	testDb,
} from '@n8n/backend-test-utils';
import { GlobalConfig } from '@n8n/config';
import type { User } from '@n8n/db';
import { WebhookRepository } from '@n8n/db';
import { Container } from '@n8n/di';
import type { INode } from 'n8n-workflow';
import { randomUUID } from 'node:crypto';

import { createOwner, createMember, createAdmin } from '@test-integration/db/users';
import { setupTestServer } from '@test-integration/utils';

import { MCP_TRIGGER_NODE_TYPE } from '@/constants';
import { OAuthTokenService } from '@/modules/oauth-server/oauth-token.service';
import { CacheService, UrlService, JwtService } from '@n8n/backend-services';

import { OAuthClientRepository } from '../database/repositories/oauth-client.repository';
import type { OAuthSessionPayload } from '../oauth-session.service';
import { sessionCookieFor, TEST_FLOW_ID } from './oauth-flow-test-utils';

/**
 * Authorization for OAuth-protected MCP Server Triggers. A workflow whose MCP
 * trigger uses `n8nOAuth2` is a protected resource; only users with
 * `workflow:execute` on that workflow may mint a token for it or invoke it.
 * Three actors exercise the access-control system: no access (denied), execute
 * via a project/resource role, and execute via a global role.
 */
const testServer = setupTestServer({ endpointGroups: ['mcp'], modules: ['oauth-server', 'mcp'] });

let owner: User;
let memberNoAccess: User;
let memberWithProjectAccess: User;
let adminWithGlobalAccess: User;

let tokenService: <REDACTED>
let jwtService: JwtService;
let oauthClientRepository: OAuthClientRepository;
let mcpEndpoint: string;

const webhookBaseUrl = () => Container.get(UrlService).getWebhookBaseUrl().replace(/\/$/, '');
const productionResourceUrl = (webhookPath: string) =>
	`${webhookBaseUrl()}/${mcpEndpoint}/${webhookPath}`;

const mcpTriggerNode = (requireExecuteAccess?: boolean): INode => ({
	id: randomUUID(),
	name: 'MCP Server Trigger',
	type: MCP_TRIGGER_NODE_TYPE,
	typeVersion: 2,
	position: [0, 0],
	parameters: {
		path: 'unused',
		authentication: 'n8nOAuth2',
		// Omitted when undefined so the "absent param ⇒ secure default" path is exercised too.
		...(requireExecuteAccess === undefined ? {} : { requireExecuteAccess }),
	},
});

/**
 * Create an active, published workflow whose MCP trigger is protected with
 * n8n OAuth2, plus the production webhook row the resolver matches on. Returns
 * the canonical resource URL the OAuth server binds tokens and consent to.
 */
const createProtectedWorkflow = async (workflowName: string, requireExecuteAccess?: boolean) => {
	const node = mcpTriggerNode(requireExecuteAccess);
	const webhookPath = randomUUID();
	const workflow = await createWorkflowWithHistory(
		{ name: workflowName, active: true, nodes: [node] },
		owner,
	);
	await setActiveVersion(workflow.id, workflow.versionId);
	await Container.get(WebhookRepository).insert({
		workflowId: workflow.id,
		webhookPath,
		method: 'POST',
		node: node.name,
	});
	return { workflow, resourceUrl: productionResourceUrl(webhookPath) };
};

const registerClient = async (grantTypes: string[] = ['authorization_code']) =>
	(
		await oauthClientRepository.save({
			id: `client-${randomUUID()}`,
			name: 'Test OAuth Client',
			redirectUris: ['https://example.com/callback'],
			grantTypes,
			tokenEndpointAuthMethod: '<REDACTED>',
		})
	).id;

const mintAccessToken = <REDACTED> (userId: string, resourceUrl: string) => {
	const clientId = await registerClient();
	const pair = tokenService.generateTokenPair(userId, clientId, resourceUrl, []);
	await tokenService.saveTokenPair(
		pair.accessToken,
		pair.refreshToken,
		clientId,
		userId,
		[],
		pair.audience,
	);
	return pair.accessToken;
};

const sessionTokenFor = <REDACTED> (resourceUrl: string) => {
	const clientId = await registerClient();
	const payload: OAuthSessionPayload = {
		clientId,
		redirectUri: 'https://example.com/callback',
		codeChallenge: 'test-challenge-string-that-is-long-enough',
		state: 'test-state',
		resource: resourceUrl,
	};
	return jwtService.sign('oauthSession', payload, { expiresIn: '10m' });
};

beforeAll(async () => {
	owner = await createOwner();
	memberNoAccess = await createMember();
	memberWithProjectAccess = await createMember();
	adminWithGlobalAccess = await createAdmin();

	tokenService = <REDACTED>
	jwtService = Container.get(JwtService);
	oauthClientRepository = Container.get(OAuthClientRepository);
	mcpEndpoint = Container.get(GlobalConfig).endpoints.mcp;
});

afterEach(async () => {
	await Container.get(CacheService).reset();
	await testDb.truncate([
		'AccessToken',
		'RefreshToken',
		'AuthorizationCode',
		'OAuthClient',
		'UserConsent',
		'WebhookEntity',
		'SharedWorkflow',
		'WorkflowEntity',
		'WorkflowHistory',
	]);
});

describe('runtime gate: verifyOAuthAccessToken enforces workflow:execute', () => {
	test('denies a user without execute access on the workflow', async () => {
		const { resourceUrl } = await createProtectedWorkflow('Owner protected workflow');
		const token = <REDACTED> mintAccessToken(memberNoAccess.id, resourceUrl);

		const result = await tokenService.verifyOAuthAccessToken(token, resourceUrl);

		expect(result.user).toBeNull();
		expect(result.context?.reason).toBe('insufficient_scope');
	});

	test('allows a user granted execute via a project role', async () => {
		const { workflow, resourceUrl } = await createProtectedWorkflow('Owner protected workflow');
		await shareWorkflowWithUsers(workflow, [memberWithProjectAccess]);
		const token = <REDACTED> mintAccessToken(memberWithProjectAccess.id, resourceUrl);

		const result = await tokenService.verifyOAuthAccessToken(token, resourceUrl);

		expect(result.user?.id).toBe(memberWithProjectAccess.id);
	});

	test('allows a user granted execute via a global role', async () => {
		const { resourceUrl } = await createProtectedWorkflow('Owner protected workflow');
		const token = <REDACTED> mintAccessToken(adminWithGlobalAccess.id, resourceUrl);

		const result = await tokenService.verifyOAuthAccessToken(token, resourceUrl);

		expect(result.user?.id).toBe(adminWithGlobalAccess.id);
	});

	test('allows any authenticated user when require-execute is turned off', async () => {
		// requireExecuteAccess:false is the opt-out — the same no-access member who is denied
		// by default must now be allowed, proving the resolver reads the per-trigger setting.
		const { resourceUrl } = await createProtectedWorkflow('Open MCP server', false);
		const token = <REDACTED> mintAccessToken(memberNoAccess.id, resourceUrl);

		const result = await tokenService.verifyOAuthAccessToken(token, resourceUrl);

		expect(result.user?.id).toBe(memberNoAccess.id);
	});
});

describe('consent gate: workflow name and authorization code require execute access', () => {
	test('does not reveal the workflow name to a user without execute access', async () => {
		const workflowName = `Owner protected workflow ${randomUUID()}`;
		const { resourceUrl } = await createProtectedWorkflow(workflowName);
		const sessionToken = <REDACTED> sessionTokenFor(resourceUrl);

		const response = await testServer
			.authAgentFor(memberNoAccess)
			.get(`/consent/details?flow=${TEST_FLOW_ID}`)
			.set('Cookie', sessionCookieFor(TEST_FLOW_ID, sessionToken));

		expect(JSON.stringify(response.body)).not.toContain(workflowName);
	});

	test('reveals the workflow name to the owner', async () => {
		const workflowName = `Owner protected workflow ${randomUUID()}`;
		const { resourceUrl } = await createProtectedWorkflow(workflowName);
		const sessionToken = <REDACTED> sessionTokenFor(resourceUrl);

		const response = await testServer
			.authAgentFor(owner)
			.get(`/consent/details?flow=${TEST_FLOW_ID}`)
			.set('Cookie', sessionCookieFor(TEST_FLOW_ID, sessionToken));

		expect(response.body.data.resourceName).toBe(workflowName);
	});

	test('does not mint an authorization code for a user without execute access', async () => {
		const { resourceUrl } = await createProtectedWorkflow('Owner protected workflow');
		const sessionToken = <REDACTED> sessionTokenFor(resourceUrl);

		const response = await testServer
			.authAgentFor(memberNoAccess)
			.post('/consent/approve')
			.set('Cookie', sessionCookieFor(TEST_FLOW_ID, sessionToken))
			.send({ approved: true, flow: TEST_FLOW_ID })
			.expect(403);

		expect(String(response.body.data?.redirectUrl ?? '')).not.toContain('code=');
	});
});

/**
 * A grant is approved for one protected resource, so every token the token endpoint
 * mints from it — including after rotation — carries that resource as its audience.
 */
describe('token endpoint: refresh grants stay on their approved resource', () => {
	const mintGrantFor = async (resourceUrl: string) => {
		const clientId = await registerClient(['authorization_code', 'refresh_token']);
		const pair = tokenService.generateTokenPair(owner.id, clientId, resourceUrl, []);
		await tokenService.saveTokenPair(
			pair.accessToken,
			pair.refreshToken,
			clientId,
			owner.id,
			[],
			pair.audience,
		);
		return { clientId, refreshToken: <REDACTED> };
	};

	const refresh = async (clientId: string, refreshToken: <REDACTED> resource?: string) =>
		await testServer.restlessAgent
			.post('/oauth/token')
			.type('form')
			.send({
				grant_type: 'refresh_token',
				refresh_token: <REDACTED>
				client_id: clientId,
				...(resource ? { resource } : {}),
			});

	test('refuses a resource the grant was not approved for, and keeps the token usable', async () => {
		const { resourceUrl: resourceA } = await createProtectedWorkflow('Workflow A');
		const { resourceUrl: resourceB } = await createProtectedWorkflow('Workflow B');
		const { clientId, refreshToken } = await mintGrantFor(resourceA);

		const denied = await refresh(clientId, refreshToken, resourceB);

		expect(denied.statusCode).toBe(400);
		expect(denied.body.error).toBe('invalid_target');

		// The refused request must not have consumed the refresh token.
		const retry = await refresh(clientId, refreshToken, resourceA);
		expect(retry.statusCode).toBe(200);
	});

	test('reuses the approved resource when the request names none', async () => {
		const { resourceUrl } = await createProtectedWorkflow('Workflow A');
		const { clientId, refreshToken } = await mintGrantFor(resourceUrl);

		const response = await refresh(clientId, refreshToken);

		expect(response.statusCode).toBe(200);
		expect(jwtService.decodeUnverified(response.body.access_token).aud).toBe(resourceUrl);
	});

	test('keeps the resource on the rotated refresh token', async () => {
		const { resourceUrl: resourceA } = await createProtectedWorkflow('Workflow A');
		const { resourceUrl: resourceB } = await createProtectedWorkflow('Workflow B');
		const { clientId, refreshToken } = await mintGrantFor(resourceA);

		const rotated = await refresh(clientId, refreshToken, resourceA);
		expect(rotated.statusCode).toBe(200);

		const crossResource = await refresh(clientId, rotated.body.refresh_token, resourceB);
		expect(crossResource.statusCode).toBe(400);
		expect(crossResource.body.error).toBe('invalid_target');

		const reused = await refresh(clientId, rotated.body.refresh_token);
		expect(reused.statusCode).toBe(200);
		expect(jwtService.decodeUnverified(reused.body.access_token).aud).toBe(resourceA);
	});
});

