describe('token audience', () => {
	test('should mint tokens whose audience is the trigger URL and reject cross-resource use', async () => {
		const pathA = randomUUID();
		const pathB = randomUUID();
		await createPublishedWebhookWorkflow(pathA, webhookNode());
		await createPublishedWebhookWorkflow(pathB, webhookNode());
		const tokenService = <REDACTED>
		const clientId = await registerOAuthClient();

		const { accessToken, refreshToken, audience } = tokenService.generateTokenPair(
			owner.id,
			clientId,
			resourceUrlFor(pathA),
			[],
		);
		await tokenService.saveTokenPair(accessToken, refreshToken, clientId, owner.id, [], audience);

		expect(decodeJwtPayload(accessToken).aud).toBe(resourceUrlFor(pathA));

		await expect(
			tokenService.verifyAccessToken(accessToken, resourceUrlFor(pathA)),
		).resolves.toMatchObject({ clientId });

		// a token minted for webhook A must fail webhook B's audience gate
		await expect(
			tokenService.verifyAccessToken(accessToken, resourceUrlFor(pathB)),
		).rejects.toThrow();
	});

	test('should scope the audience per method so disjoint-method triggers do not share a token', async () => {
		// Same path, two triggers (GET vs POST): each trigger's audiences cover only its
		// own methods, so a token minted for the GET trigger is rejected at the POST one.
		const sharedPath = randomUUID();
		await createPublishedWebhookWorkflow(sharedPath, webhookNode({ name: 'GetHook' }), {
			methods: ['GET'],
		});
		await createPublishedWebhookWorkflow(sharedPath, webhookNode({ name: 'PostHook' }), {
			methods: ['POST'],
		});
		const tokenService = <REDACTED>
		const clientId = await registerOAuthClient();

		const getResource = resourceUrlFor(sharedPath, 'GET');
		const { accessToken, refreshToken, audience } = tokenService.generateTokenPair(
			owner.id,
			clientId,
			getResource,
			[],
		);
		await tokenService.saveTokenPair(accessToken, refreshToken, clientId, owner.id, [], audience);

		expect(decodeJwtPayload(accessToken).aud).toBe(getResource);

		await expect(tokenService.verifyAccessToken(accessToken, getResource)).resolves.toMatchObject({
			clientId,
		});

		// replaying the GET-scoped token against the POST trigger on the same path must fail
		await expect(
			tokenService.verifyAccessToken(accessToken, resourceUrlFor(sharedPath, 'POST')),
		).rejects.toThrow();
	});

	test('should accept a token across the methods of a single trigger', async () => {
		// One trigger on GET+POST: a token minted from the GET challenge must work when
		// the same trigger is called with POST — the method selects, it does not scope.
		const webhookPath = randomUUID();
		await createPublishedWebhookWorkflow(webhookPath, webhookNode(), { methods: ['GET', 'POST'] });
		const tokenService = <REDACTED>
		const clientId = await registerOAuthClient();

		const { accessToken, refreshToken, audience } = tokenService.generateTokenPair(
			owner.id,
			clientId,
			resourceUrlFor(webhookPath, 'GET'),
			[],
		);
		await tokenService.saveTokenPair(accessToken, refreshToken, clientId, owner.id, [], audience);

		await expect(
			tokenService.verifyAccessToken(accessToken, resourceUrlFor(webhookPath, 'POST')),
		).resolves.toMatchObject({ clientId });
	});

	test('should mint the canonical audience for an equivalent resource spelling', async () => {
		// The `?method=` selector is matched case-insensitively, so a client may present
		// a spelling the resource does not itself declare. The minted `aud` must still be
		// the canonical one, or the gate — which checks `getAudiences()` — could never
		// accept the token.
		const webhookPath = randomUUID();
		await createPublishedWebhookWorkflow(webhookPath, webhookNode());
		const oauthServerService = Container.get(OAuthServerService);

		const resolved = await (
			oauthServerService as unknown as {
				resolveAndValidateResourceIndicator: (resource: string) => Promise<string | undefined>;
			}
		).resolveAndValidateResourceIndicator(
			`${webhookBaseUrl()}/${webhookEndpoint}/${webhookPath}?method=post`,
		);

		expect(resolved).toBe(resourceUrlFor(webhookPath, 'POST'));
	});

	test('should keep an existing token valid after the trigger gains a method', async () => {
		const webhookPath = randomUUID();
		const workflow = await createPublishedWebhookWorkflow(webhookPath, webhookNode(), {
			methods: ['GET'],
		});
		const tokenService = <REDACTED>
		const clientId = await registerOAuthClient();

		const getResource = resourceUrlFor(webhookPath, 'GET');
		const { accessToken, refreshToken, audience } = tokenService.generateTokenPair(
			owner.id,
			clientId,
			getResource,
			[],
		);
		await tokenService.saveTokenPair(accessToken, refreshToken, clientId, owner.id, [], audience);

		// the user adds POST to the node; the GET-scoped token must survive
		await insertWebhookRow(workflow.id, webhookPath, 'Webhook', 'POST');
		await Container.get(CacheService).reset();

		await expect(tokenService.verifyAccessToken(accessToken, getResource)).resolves.toMatchObject({
			clientId,
		});
	});
});

import {
	hasAzureApiKey,
	hasAzureEntraToken,
	isAzureEntraCredential,
} from '../provider-credentials';

describe('azure-openai auth predicates', () => {
	describe('hasAzureApiKey', () => {
		it('treats a non-empty string as present', () => {
			expect(hasAzureApiKey({ apiKey: '<REDACTED>' })).toBe(true);
		});

		it('treats a whitespace-only string as absent', () => {
			expect(hasAzureApiKey({ apiKey: '   ' })).toBe(false);
		});

		it('treats undefined / non-string as absent', () => {
			expect(hasAzureApiKey({})).toBe(false);
			expect(hasAzureApiKey({ apiKey: <REDACTED> })).toBe(false);
			expect(hasAzureApiKey({ apiKey: <REDACTED> })).toBe(false);
		});
	});

	describe('hasAzureEntraToken', () => {
		it('treats a stored access_token as Entra', () => {
			expect(hasAzureEntraToken({ oauthTokenData: <REDACTED> access_token: '<REDACTED>' } })).toBe(true);
		});

		it('treats an oauthTokenData object without access_token as not Entra', () => {
			expect(hasAzureEntraToken({ oauthTokenData: <REDACTED> })).toBe(false);
		});

		it('treats undefined / non-object oauthTokenData as not Entra', () => {
			expect(hasAzureEntraToken({})).toBe(false);
			expect(hasAzureEntraToken({ oauthTokenData: <REDACTED> })).toBe(false);
			expect(hasAzureEntraToken({ oauthTokenData: '<REDACTED>' })).toBe(false);
		});
	});

	describe('isAzureEntraCredential', () => {
		it('is Entra when no usable apiKey and a stored access_token', () => {
			expect(isAzureEntraCredential({ oauthTokenData: <REDACTED> access_token: '<REDACTED>' } })).toBe(
				true,
			);
		});

		it('is not Entra when a usable apiKey is present even with a stored token', () => {
			expect(
				isAzureEntraCredential({
					apiKey: '<REDACTED>',
					oauthTokenData: <REDACTED> access_token: '<REDACTED>' },
				}),
			).toBe(false);
		});

		it('is not Entra when apiKey is whitespace-only and no token is stored', () => {
			expect(isAzureEntraCredential({ apiKey: '   ' })).toBe(false);
		});
	});
});

import type { AgentJsonToolConfig, AiGatewayConfigDto } from '@n8n/api-types';
import type { INodeType, INodeTypeDescription } from 'n8n-workflow';
import { mock } from 'vitest-mock-extended';

import type { NodeTypes } from '@/node-types';

import {
	assignCredentialToNodeTools,
	listAiGatewayManagedCredentialTypes,
	reconcileNodeToolGatewayCredentials,
} from '../reconcile-node-tool-gateway-credentials';

const GATEWAY_CONFIG = {
	nodes: ['n8n-nodes-base.slack'],
	credentialTypes: ['slackApi'],
	providerConfig: {},
} as unknown as AiGatewayConfigDto;

const SERVICE_GATEWAY_CONFIG = {
	nodes: ['n8n-nodes-base.service'],
	credentialTypes: ['serviceApiKey'],
	providerConfig: {},
} as unknown as AiGatewayConfigDto;

const SENTINEL = { id: null, name: 'Gateway credits', __aiGatewayManaged: true } as const;

const NO_OWNED = new Set<string>();

function nodeTypesWithDescription(description: INodeTypeDescription): NodeTypes {
	const nodeTypes = mock<NodeTypes>();
	nodeTypes.getByNameAndVersion.mockReturnValue({ description } as INodeType);
	return nodeTypes;
}

function nodeTypesWithCredentials(credentialNames: string[]): NodeTypes {
	return nodeTypesWithDescription({
		displayName: 'x',
		name: 'x',
		group: [],
		version: 1,
		description: '',
		defaults: {},
		inputs: [],
		outputs: [],
		properties: [],
		credentials: credentialNames.map((name) => ({ name })),
	} as INodeTypeDescription);
}

const multiAuthNodeDescription = {
	displayName: 'Service',
	name: 'n8n-nodes-base.service',
	group: [],
	version: 1,
	description: '',
	defaults: {},
	inputs: [],
	outputs: [],
	credentials: [
		{ name: 'serviceOAuth2Api', displayOptions: { show: { authentication: ['oAuth2'] } } },
		{ name: 'serviceApiKey', displayOptions: { show: { authentication: ['apiKey'] } } },
	],
	properties: [
		{
			displayName: 'Authentication',
			name: 'authentication',
			type: 'options',
			options: [
				{ name: 'OAuth2', value: 'oAuth2' },
				{ name: 'API Key', value: 'apiKey' },
			],
			default: 'oAuth2',
		},
	],
} as INodeTypeDescription;

function nodeTool(
	nodeType: string,
	credentials?: Extract<AgentJsonToolConfig, { type: 'node' }>['node']['credentials'],
): Extract<AgentJsonToolConfig, { type: 'node' }> {
	return {
		type: 'node',
		name: 'Tool',
		node: { nodeType, nodeTypeVersion: 1, nodeParameters: {}, credentials },
	};
}

describe('reconcileNodeToolGatewayCredentials', () => {
	it('auto-assigns the managed credential to a covered, empty, required slot', () => {
		const tools = [nodeTool('n8n-nodes-base.slackTool')];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ slackApi: SENTINEL });
	});

	it('leaves a real credential untouched (BYOK wins)', () => {
		const tools = [
			nodeTool('n8n-nodes-base.slackTool', { slackApi: { id: 'c1', name: 'My Slack' } }),
		];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ slackApi: { id: 'c1', name: 'My Slack' } });
	});

	it('assigns the managed credential over a slot whose id was cleared by sanitization', () => {
		// sanitizeUnknownAgentCredentials clears an inaccessible id to '' — the
		// slot is effectively empty (validation flags it missing) and must pick
		// up the managed credential like any other empty slot.
		const tools = [nodeTool('n8n-nodes-base.slackTool', { slackApi: { id: '', name: 'Old' } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ slackApi: SENTINEL });
	});

	it('does not assign for a service the gateway does not cover', () => {
		const tools = [nodeTool('n8n-nodes-base.notionTool')];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['notionApi']),
			GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toBeUndefined();
	});

	it('does not auto-assign to an HTTP request tool even when the gateway covers it', () => {
		// Defense-in-depth mirroring MCP: an HTTP node calls a user-controlled
		// URL, so a managed credential is never attached automatically.
		const tools = [nodeTool('n8n-nodes-base.httpRequestTool')];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['httpBasicAuth']),
			{
				nodes: ['n8n-nodes-base.httpRequest'],
				credentialTypes: ['httpBasicAuth'],
				providerConfig: {},
			} as unknown as AiGatewayConfigDto,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toBeUndefined();
	});

	it('keeps an eligible inbound managed marker on an HTTP request tool (explicit opt-in)', () => {
		const tools = [nodeTool('n8n-nodes-base.httpRequestTool', { httpBasicAuth: { ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['httpBasicAuth']),
			{
				nodes: ['n8n-nodes-base.httpRequest'],
				credentialTypes: ['httpBasicAuth'],
				providerConfig: {},
			} as unknown as AiGatewayConfigDto,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ httpBasicAuth: SENTINEL });
	});

	it('does not auto-assign when the project already has a credential of the type (own credential wins)', () => {
		const tools = [nodeTool('n8n-nodes-base.slackTool')];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			GATEWAY_CONFIG,
			new Set(['slackApi']),
		);
		expect(tools[0].node.credentials).toBeUndefined();
	});

	it('keeps an explicit inbound managed marker even when the project has a credential of the type', () => {
		// An inbound marker is an explicit choice (manual toggle or the user
		// asking the builder for n8n credits) — own credentials must not veto it.
		const tools = [nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			GATEWAY_CONFIG,
			new Set(['slackApi']),
		);
		expect(tools[0].node.credentials).toEqual({ slackApi: SENTINEL });
	});

	it('does not switch auth to a sibling type the project has a credential for', () => {
		const tools = [nodeTool('n8n-nodes-base.serviceTool')];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithDescription(multiAuthNodeDescription),
			SERVICE_GATEWAY_CONFIG,
			new Set(['serviceApiKey']),
		);
		expect(tools[0].node.credentials).toBeUndefined();
		expect(tools[0].node.nodeParameters).toEqual({});
	});

	it('switches auth to a supported sibling credential type when the displayed type is unsupported', () => {
		const tools = [nodeTool('n8n-nodes-base.serviceTool')];

		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithDescription(multiAuthNodeDescription),
			SERVICE_GATEWAY_CONFIG,
			NO_OWNED,
		);

		expect(tools[0].node.credentials).toEqual({ serviceApiKey: <REDACTED> });
		expect(tools[0].node.nodeParameters).toEqual({ authentication: 'apiKey' });
	});

	it('switches auth while preserving unrelated parameters when the auth selector relies on its default', () => {
		const tools = [nodeTool('n8n-nodes-base.serviceTool')];
		tools[0].node.nodeParameters = { operation: 'split' };

		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithDescription({
				...multiAuthNodeDescription,
				properties: [
					{
						displayName: 'Operation',
						name: 'operation',
						type: 'options',
						options: [{ name: 'Split', value: 'split' }],
						default: 'split',
					},
					...multiAuthNodeDescription.properties,
				],
			}),
			SERVICE_GATEWAY_CONFIG,
			NO_OWNED,
		);

		expect(tools[0].node.credentials).toEqual({ serviceApiKey: <REDACTED> });
		expect(tools[0].node.nodeParameters).toEqual({
			operation: 'split',
			authentication: 'apiKey',
		});
	});

	it('does not rewrite an auth parameter that already activates the supported credential', () => {
		const tools = [nodeTool('n8n-nodes-base.serviceTool')];
		tools[0].node.nodeParameters = { authentication: 'apiKeyLegacy' };

		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithDescription({
				...multiAuthNodeDescription,
				credentials: [
					{
						name: 'serviceApiKey',
						displayOptions: { show: { authentication: ['apiKey', 'apiKeyLegacy'] } },
					},
				],
			}),
			SERVICE_GATEWAY_CONFIG,
			NO_OWNED,
		);

		expect(tools[0].node.credentials).toEqual({ serviceApiKey: <REDACTED> });
		expect(tools[0].node.nodeParameters).toEqual({ authentication: 'apiKeyLegacy' });
	});

	it('activates the auth parameter for an explicit marker on an inactive alternate auth slot', () => {
		// Marker on the API-key slot while `authentication` still defaults to
		// OAuth (and the project owns the OAuth type): without activation the
		// marker is inert and the tool cannot run.
		const tools = [nodeTool('n8n-nodes-base.serviceTool', { serviceApiKey: <REDACTED> ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithDescription(multiAuthNodeDescription),
			SERVICE_GATEWAY_CONFIG,
			new Set(['serviceOAuth2Api']),
		);
		expect(tools[0].node.credentials).toEqual({ serviceApiKey: <REDACTED> });
		expect(tools[0].node.nodeParameters).toEqual({ authentication: 'apiKey' });
	});

	it('leaves parameters untouched when the marked slot is already active', () => {
		const tools = [nodeTool('n8n-nodes-base.serviceTool', { serviceApiKey: <REDACTED> ...SENTINEL } })];
		tools[0].node.nodeParameters = { authentication: 'apiKey' };
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithDescription(multiAuthNodeDescription),
			SERVICE_GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ serviceApiKey: <REDACTED> });
		expect(tools[0].node.nodeParameters).toEqual({ authentication: 'apiKey' });
	});

	it('keeps an eligible marker on a slot the node description does not declare', () => {
		// HTTP predefined credential types are not in description.credentials, so
		// no activation resolves; the explicit marker must survive untouched.
		const tools = [nodeTool('n8n-nodes-base.httpRequestTool', { serviceApiKey: <REDACTED> ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials([]),
			{
				nodes: ['n8n-nodes-base.httpRequest'],
				credentialTypes: ['serviceApiKey'],
				providerConfig: {},
			} as unknown as AiGatewayConfigDto,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ serviceApiKey: <REDACTED> });
		expect(tools[0].node.nodeParameters).toEqual({});
	});

	it('deletes an inbound managed marker on an uncovered slot (trust gate)', () => {
		const tools = [nodeTool('n8n-nodes-base.notionTool', { notionApi: { ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['notionApi']),
			GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({});
	});

	it('canonicalizes an eligible managed marker, dropping smuggled fields', () => {
		const tools = [
			nodeTool('n8n-nodes-base.slackTool', {
				slackApi: {
					id: null,
					name: 'hacked',
					__aiGatewayManaged: true,
					injected: 'x',
				} as never,
			}),
		];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			GATEWAY_CONFIG,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({ slackApi: SENTINEL });
	});

	it('drops all managed markers when no gateway config is available', () => {
		const tools = [nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			undefined,
			NO_OWNED,
		);
		expect(tools[0].node.credentials).toEqual({});
	});

	it('drops managed markers when the node type cannot be resolved', () => {
		const nodeTypes = mock<NodeTypes>();
		nodeTypes.getByNameAndVersion.mockImplementation(() => {
			throw new Error('unknown node type');
		});
		const tools = [nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } })];
		reconcileNodeToolGatewayCredentials(tools, nodeTypes, GATEWAY_CONFIG, NO_OWNED);
		expect(tools[0].node.credentials).toEqual({});
	});
});

describe('listAiGatewayManagedCredentialTypes', () => {
	it('returns a type whose every required slot is served by a managed credential', () => {
		const tools = [nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } })];
		expect(
			listAiGatewayManagedCredentialTypes(tools, nodeTypesWithCredentials(['slackApi'])),
		).toEqual(['slackApi']);
	});

	it('treats a real credential of the type as satisfying the slot', () => {
		const tools = [
			nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } }),
			nodeTool('n8n-nodes-base.slackTool', { slackApi: { id: 'c1', name: 'My Slack' } }),
		];
		expect(
			listAiGatewayManagedCredentialTypes(tools, nodeTypesWithCredentials(['slackApi'])),
		).toEqual(['slackApi']);
	});

	it('excludes a managed type that still has an empty required slot on another tool', () => {
		// Per-operation coverage: one tool runs a covered operation on n8n credits,
		// another needs a real credential for an uncovered one — so the type must
		// keep prompting rather than be suppressed globally.
		const tools = [
			nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } }),
			nodeTool('n8n-nodes-base.slackTool'),
		];
		expect(
			listAiGatewayManagedCredentialTypes(tools, nodeTypesWithCredentials(['slackApi'])),
		).toEqual([]);
	});

	it('ignores non-node tools and unresolvable node types', () => {
		const nodeTypes = mock<NodeTypes>();
		nodeTypes.getByNameAndVersion.mockImplementation(() => {
			throw new Error('unknown node type');
		});
		const tools = [nodeTool('n8n-nodes-base.slackTool', { slackApi: { ...SENTINEL } })];
		expect(listAiGatewayManagedCredentialTypes(tools, nodeTypes)).toEqual([]);
	});
});

describe('assignCredentialToNodeTools', () => {
	const credential = { id: 'g1', name: 'Gmail account' };

	it('fills every empty slot of the type and counts them', () => {
		const tools = [nodeTool('n8n-nodes-base.gmailTool'), nodeTool('n8n-nodes-base.gmailTool')];
		const filled = assignCredentialToNodeTools(
			tools,
			nodeTypesWithCredentials(['gmailOAuth2']),
			'gmailOAuth2',
			credential,
		);
		expect(filled).toBe(2);
		expect(tools.map((t) => t.node.credentials)).toEqual([
			{ gmailOAuth2: credential },
			{ gmailOAuth2: credential },
		]);
	});

	it('keeps a real credential and a managed marker', () => {
		const tools = [
			nodeTool('n8n-nodes-base.gmailTool', { gmailOAuth2: { id: 'other', name: 'Other' } }),
			nodeTool('n8n-nodes-base.gmailTool', { gmailOAuth2: { ...SENTINEL } }),
		];
		const filled = assignCredentialToNodeTools(
			tools,
			nodeTypesWithCredentials(['gmailOAuth2']),
			'gmailOAuth2',
			credential,
		);
		expect(filled).toBe(0);
		expect(tools[0].node.credentials).toEqual({ gmailOAuth2: { id: 'other', name: 'Other' } });
		expect(tools[1].node.credentials).toEqual({ gmailOAuth2: SENTINEL });
	});

	it('skips a node whose type does not declare the credential', () => {
		const tools = [nodeTool('n8n-nodes-base.slackTool')];
		const filled = assignCredentialToNodeTools(
			tools,
			nodeTypesWithCredentials(['slackApi']),
			'gmailOAuth2',
			credential,
		);
		expect(filled).toBe(0);
		expect(tools[0].node.credentials).toBeUndefined();
	});

	it('skips a slot hidden by the current authentication option', () => {
		const tools = [nodeTool('n8n-nodes-base.service')];
		const filled = assignCredentialToNodeTools(
			tools,
			nodeTypesWithDescription(multiAuthNodeDescription),
			'serviceApiKey',
			{ id: 'k1', name: 'Key' },
		);
		expect(filled).toBe(0);
	});
});

