const formTriggerNode = (trustedSource?: string): INode => ({
	id: randomUUID(),
	name: 'On form submission',
	type: FORM_TRIGGER_NODE_TYPE,
	typeVersion: 2,
	position: [0, 0],
	// `requireExecuteAccess` is opt-in, so set it explicitly: these tests exercise the
